$want = @('context:new-school','context:new-school-animals-with-attitude','context:new-school-body-bending-perspective','context:new-school-dragons-monsters-and-creatures','context:new-school-graffiti-street-and-color','context:new-school-machines-cars-and-objects','context:new-school-people-faces-and-characters','context:new-school-pure-new-school','context:new-school-push-new-school','context:new-school-skulls-demons-and-darkness','context:new-school-surreal-worlds-and-impossible-things')
$tmp = Join-Path $env:TEMP "aura-ctx-new-school.json"
ConvertTo-Json @($want) | Set-Content -Path $tmp -Encoding utf8
$out = (npx wrangler kv bulk get $tmp --namespace-id $ns --remote 2>$null | Out-String)
$hits = [regex]::Matches($out, '"(context:[^"]+)":\s*"((?:[^"\\]|\\.)*)"')
if ($hits.Count -eq 0) { "  none found" } else { foreach ($h in $hits) { "  removed " + $h.Groups[1].Value + ": " + $h.Groups[2].Value; npx wrangler kv key delete --namespace-id $ns $h.Groups[1].Value --remote 2>$null | Out-Null }; "  waiting 70 seconds"; Start-Sleep -Seconds 70 }
foreach ($c in $cats.Keys) { RUN ("REDO " + $final[$test[$c]]) }
